/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, toggle switch, cool toggle */
.__UIV_SCOPE__ .checkbox-wrapper *,
  .__UIV_SCOPE__ .checkbox-wrapper *::before,
  .__UIV_SCOPE__ .checkbox-wrapper *::after {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper label {
  display: block;
  width: 35px;
  height: 35px;
  cursor: pointer;
}

.__UIV_SCOPE__ .checkbox-wrapper input {
  visibility: hidden;
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper input:checked ~ .checkbox {
  transform: rotate(45deg);
  width: 14px;
  margin-left: 12px;
  border-color: #000000;
  border-top-color: transparent;
  border-left-color: transparent;
  border-radius: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper .checkbox {
  display: block;
  width: inherit;
  height: inherit;
  border: 3px solid #434343;
  border-radius: 6px;
  transition: all 0.375s;
}
